fn diff(&self, base: &PdfSnapshot) -> MutationOutcome<PdfDiff> {
    let mut candidate = base.clone();
    candidate.objects = self.graph.objects.clone();
    candidate.catalog_extra = self.graph.catalog_extra.clone();
    if crate::standards::v1_7::subsets::base::schema::conformance_support::admitted_first_page(&candidate).is_none() { return MutationOutcome::refuse("mutation.target-missing", "Restored DPart graph requires the retained genuine Page tree", ["DPartRoot"]); }
    MutationOutcome::new(PdfDiff { raw_graph: Some(self.graph.clone()), ..Default::default() })
}

export function applyRestoreDpartGraph(base: PdfSnapshot, mutation: RestoreDpartGraphMutation): PdfSnapshot {
  const candidate = {...base,objects:structuredClone(mutation.graph.objects),catalogExtra:structuredClone(mutation.graph.catalogExtra)};
  if (!admittedFirstPage(candidate)) throw new Error('Restored DPart graph requires the retained genuine Page tree');
  return candidate;
}
